INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, features, published_at) VALUES ('e3bf5abf-4332-5863-8c5e-e88799aec967', 'P_133963537', 'APARTMENT', 'bán căn hộ chung cư CT2A Hoàng Cầu sổ đỏ 58m giá 5,8 tỷ', 'Em cần b.á.n căn hộ CT2A Hoàng Cầu, cạnh hồ Hoàng Cầu. Sảnh đẹp nhất khu. Diện tích sổ đỏ 58,1m2. 1 khách, 2 ngủ, 1 bếp, 1 WC. Tầng đẹp. Căn góc thoáng sáng. Giá dịch vụ tòa nhà 4k/m2 và gửi xe siêu rẻ. Thang máy Mitsubishi (Nhật Bản) chạy an toàn, mật độ căn hộ thấp, ko phải chờ đợi thang. Vị trí lõi trung tâm nên xung quanh tiện ích ngập tràn, cạnh hồ Hoàng Cầu, cách ga tàu điện Cát Linh - Hà Đông khoảng 300m, di chuyển thuận tiện các ngả. Đường vành đai I đoạn Hoàng Cầu - Voi Phục dần hoàn thiện, giá trị căn hộ lại tăng cao. Rất hợp với bác nào vừa bị giải tỏa làm đường vành đai I, phải chuyển đi chỗ khác mà lại vẫn muốn ở khu Hoàng Cầu. Hoặc bác nào có con học ở trường Nguyễn Trường Tộ, THCS Hoàng Cầu thì quá tuyệt vời. Hiện nhà em đang cho thuê ổn định 12 triệu/1 tháng. Cô tổ trưởng tốt bụng, nhiệt tình. An ninh tốt. G.i.á b.á.n: 5 t.ỷ 800 t.r.i.ệ.u. Nhà thật, ảnh thật, g.i.á thật. Anh chị cô bác nào có nhu cầu mua thì liên hệ với e ạ: *** Em cảm ơn', 'AVAILABLE', 'Số 36, Hoàng Cầu, Phường Ô Chợ Dừa, Quận Đống Đa, Hà Nội', 'Phường Ô Chợ Dừa', 'Quận Đống Đa', 'Hà Nội', 21.018200, 105.824170, 58.00, 2, 1, 15, 'Nam', 'Sổ hồng riêng', 5800000000.00, 'VND', '{"apartment_type":"Chung cư","balcony_direction":"Đông Bắc","crawled_at":"2026-08-05T09:26:33.698022Z","deposit":null,"furniture_status":"Nội thất đầy đủ","listing_type":"SALE","price_period":"TOTAL","project_name":"Chung cư tái định cư Hoàng Cầu","seller":{"display_name":"Felix Hoàng","is_company":false,"rating":null,"source_account_id":"32272720"},"source":"NHATOT","source_api_url":"https://gateway.chotot.com/v1/public/ad-listing/133963537","source_listing_id":133963537,"unit_number":null}'::jsonb, '2026-08-05T09:23:41Z'::timestamptz) ON CONFLICT (code) DO UPDATE SET property_kind = EXCLUDED.property_kind, title = EXCLUDED.title, description = EXCLUDED.description, status = CASE WHEN properties.status IN ('DRAFT', 'AVAILABLE') THEN EXCLUDED.status ELSE properties.status END, address_line = EXCLUDED.address_line, ward = EXCLUDED.ward, district = EXCLUDED.district, province = EXCLUDED.province, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, area_sqm = EXCLUDED.area_sqm, bedrooms = EXCLUDED.bedrooms, bathrooms = EXCLUDED.bathrooms, floor_number = EXCLUDED.floor_number, orientation = EXCLUDED.orientation, legal_status = EXCLUDED.legal_status, list_price = EXCLUDED.list_price, currency = EXCLUDED.currency, features = EXCLUDED.features, published_at = EXCLUDED.published_at, updated_at = now();
