INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, features, published_at) VALUES ('9d7f7400-3f87-5f67-87e4-64415ed1293e', 'P_133131903', 'APARTMENT', 'Căn hộ chung cư tòa CT1 gelexia riverside Hoàng Mai 73,3m 2 ngủ', 'Nhà cửa đứa em cùng cty với em ạ, hai ae ở cùng tòa quý anh chị có nhu cầu căn hộ chung cư tại khu vực tam trinh, hoàng mai hà nội thì liên hệ em qua xem nhà, khu gelexia riverside gần gamuada, gần trường chất lượng cao Hoàng mai cấp 1 và 2 vừa xây xong và vận hành đầu năm nay, trong khu còn có 2 trường tiểu học và thcs Tam trinh cách chân tòa nhà 100m bắt đầu tuyển sinh cho năm học mới đầu tháng 9 này, ngoài ra dưới nội khu còn đang xây trường mầm non công lập hiện đại dự kiển sang năm học sau sẽ đi vào vận hành. ngoài ra khu em còn gần bệnh viện đại học y cơ sở 2 cách 100m, đường tam trinh đang xây dựng rất nhanh ạ, đến cuối năm đường rộng gấp 3 rất thuận tiện giao thông', 'AVAILABLE', '885, Tam Trinh, Phường Yên Sở, Quận Hoàng Mai, Hà Nội', 'Phường Yên Sở', 'Quận Hoàng Mai', 'Hà Nội', 20.973660, 105.866310, 73.30, 2, 2, 5, 'Nam', 'Sổ hồng riêng', 5499000000.00, 'VND', '{"apartment_type":"Chung cư","balcony_direction":"Bắc","crawled_at":"2026-08-05T09:26:33.698022Z","deposit":null,"furniture_status":"Hoàn thiện cơ bản","listing_type":"SALE","price_period":"TOTAL","project_name":"Gelexia Riverside","seller":{"display_name":"Mr Long","is_company":false,"rating":5.0,"source_account_id":"12507569"},"source":"NHATOT","source_api_url":"https://gateway.chotot.com/v1/public/ad-listing/133131903","source_listing_id":133131903,"unit_number":null}'::jsonb, '2026-06-22T14:30:04Z'::timestamptz) ON CONFLICT (code) DO UPDATE SET property_kind = EXCLUDED.property_kind, title = EXCLUDED.title, description = EXCLUDED.description, status = CASE WHEN properties.status IN ('DRAFT', 'AVAILABLE