INSERT INTO properties (id, code, property_kind, title, description, status, address_line, ward, district, province, latitude, longitude, area_sqm, bedrooms, bathrooms, floor_number, orientation, legal_status, list_price, currency, features, published_at) VALUES ('12ede470-801b-5892-868f-ce6cce4f33bd', 'P_132839848', 'APARTMENT', 'Bán căn hộ chung cư Bộ Kế hoạch và Đầu tư , Đông Quan, Cầu Giấy', 'Bán căn hộ chung cư Bộ Kế hoạch và Đầu tư ngõ 1 Đông Quan, tổ 1 Quan Hoa, phường Nghĩa Đô, diện tích thông thủy 84 m2, chưa bao gồm 6 m2 loggia, tầng cao, full nội thất.  Chung cư Bộ Kế Hoạch & Đầu tư Quan Hoa nằm ở vị trí trung tâm giao thông thuận tiện, Gần trường THCS FPT, đường thông sang Nguyễn Khánh Toàn, Đông Quan, Nghĩa Tân. Thiết kế  Phòng khách, bếp ăn, 2phòng ngủ + 2wc + loggia.  Phí dịch: 100k +45k gửi xe máy/tháng. Sổ đỏ chính chủ. Giá 7,xxx tỷ.', 'AVAILABLE', 'số 39, Quan Hoa, Phường Quan Hoa, Quận Cầu Giấy, Hà Nội', 'Phường Quan Hoa', 'Quận Cầu Giấy', 'Hà Nội', 21.032330, 105.802590, 84.00, 2, 2, 7, 'Bắc', 'Sổ hồng riêng', 7200000000.00, 'VND', '{"apartment_type":"Chung cư","balcony_direction":"Tây","crawled_at":"2026-08-05T09:26:33.698022Z","deposit":null,"furniture_status":"Nội thất đầy đủ","listing_type":"SALE","price_period":"TOTAL","project_name":"Chung cư Bộ Kế Hoạch Đầu Tư Quan Hoa","seller":{"display_name":"Vuong K Hoa","is_company":false,"rating":null,"source_account_id":"31786479"},"source":"NHATOT","source_api_url":"https://gateway.chotot.com/v1/public/ad-listing/132839848","source_listing_id":132839848,"unit_number":null}'::jsonb, '2026-06-07T07:51:11Z'::timestamptz) ON CONFLICT (code) DO UPDATE SET property_kind = EXCLUDED.property_kind, title = EXCLUDED.title, description = EXCLUDED.description, status = CASE WHEN properties.status IN ('DRAFT', 'AVAILABLE') THEN EXCLUDED.status ELSE properties.status END, address_line = EXCLUDED.address_line, ward = EXCLUDED.ward, district = EXCLUDED.district, province = EXCLUDED.province, latitude = EXCLUDED.la